/**
 * Binary GIF test fixtures
 */

export const MINIMAL_ANIMATED_GIF = Buffer.from([
  // GIF Header
  0x47, 0x49, 0x46, 0x38, 0x39, 0x61,
  // Logical Screen Descriptor: 10x10, GCT size=1 (4 entries)
  0x0a, 0x00, 0x0a, 0x00, 0x91, 0x00, 0x00,
  // Global Color Table: red, blue, black, black
  0xff, 0x00, 0x00, 0x00, 0x00, 0xff, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  // Frame 1 GCE: disposal=1, delay=10cs (100ms)
  0x21, 0xf9, 0x04, 0x04, 0x0a, 0x00, 0x00, 0x00,
  // Frame 1 Image Descriptor: 10x10, no LCT
  0x2c, 0x00, 0x00, 0x00, 0x00, 0x0a, 0x00, 0x0a, 0x00, 0x00,
  // Frame 1 LZW data (100 red pixels, min code size 2)
  0x02, 0x16, 0x8c, 0x2d, 0x99, 0x87, 0x2a, 0x1c, 0xdc, 0x33, 0xa0, 0x02, 0x75, 0xec, 0x95, 0xfa,
  0xa8, 0xde, 0x60, 0x8c, 0x04, 0x91, 0x4c, 0x01, 0x00,
  // Frame 2 GCE: disposal=2, delay=20cs (200ms)
  0x21, 0xf9, 0x04, 0x08, 0x14, 0x00, 0x00, 0x00,
  // Frame 2 Image Descriptor
  0x2c, 0x00, 0x00, 0x00, 0x00, 0x0a, 0x00, 0x0a, 0x00, 0x00,
  // Frame 2 LZW data (100 blue pixels)
  0x02, 0x16, 0x8c, 0x2d, 0x99, 0x87, 0x2a, 0x1c, 0xdc, 0x33, 0xa0, 0x02, 0x75, 0xec, 0x95, 0xfa,
  0xa8, 0xde, 0x60, 0x8c, 0x04, 0x91, 0x4c, 0x01, 0x00,
  // GIF Trailer
  0x3b,
]);

export function animatedGifBuffer() {
  const ab = new ArrayBuffer(MINIMAL_ANIMATED_GIF.length);
  const view = new Uint8Array(ab);
  for (let i = 0; i < MINIMAL_ANIMATED_GIF.length; i++) {
    view[i] = MINIMAL_ANIMATED_GIF[i];
  }
  return ab;
}
